type exerciseRoutineJoins[Q dialect.Joinable] struct {
	typ      string
	Exercise modAs[Q, exerciseColumns]
	Routine  modAs[Q, routineColumns]
}

func (j exerciseRoutineJoins[Q]) aliasedAs(alias string) exerciseRoutineJoins[Q] {
	return buildExerciseRoutineJoins[Q](buildExerciseRoutineColumns(alias), j.typ)
}

func buildExerciseRoutineJoins[Q dialect.Joinable](cols exerciseRoutineColumns, typ string) exerciseRoutineJoins[Q] {
	return exerciseRoutineJoins[Q]{
		typ: typ,
		Exercise: modAs[Q, exerciseColumns]{
			c: Exercises.Columns,
			f: func(to exerciseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Exercises.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ExerciseID),
					))
				}

				return mods
			},
		},
		Routine: modAs[Q, routineColumns]{
			c: Routines.Columns,
			f: func(to routineColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Routines.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoutineID),
					))
				}

				return mods
			},
		},
	}
}
